{
  "title": "The Glass Diver's Escape",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a shattered map of the ruined city.",
      "visual_description": "Mara stands at a broken stone table under a faded royal banner, tracing the torn edges of a parchment map with ink-stained fingers. Behind her, the city's collapsed towers rise against a smoky sky.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The glass diver arrives through a cracked window.",
      "visual_description": "A figure in a clear diving helmet and a coat reflecting broken city lights steps through a fractured stained-glass window, shards reforming behind him.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers a warning about the castle gates.",
      "visual_description": "The oracle lamp sits on a rusted brazier, its single glowing eye in the flame darting toward the distant, iron-bound castle gates that loom in twilight.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The sleeping tax collector snores on a stamp-piled desk.",
      "visual_description": "In a collapsed guardhouse, the sleeping tax collector uses a ledger book as a pillow, stamped papers stuck to his sleeves, oblivious to the dust and rubble.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "The tin fox scouts ahead through a rubble-choked street.",
      "visual_description": "The small metal fox with a key-wind tail and blue glass eyes picks its way over broken cobblestones, past a fallen royal banner trailing in mud.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara and the glass diver meet at a cursed tower's base.",
      "visual_description": "At the foot of a twisted black tower, Mara unrolls her map while the glass diver peers up at the spiraling runes that glow faintly on the stone.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "The oracle lamp warns of armored patrols near the market square.",
      "visual_description": "The lamp's flame eye casts a red light across a deserted square, empty armor suits clanking in an unseen wind, their visors dark.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox discovers a secret passage behind a magic door.",
      "visual_description": "The metal fox scratches at a stone wall where a faint outline of a door shimmers with arcane symbols, its blue eyes reflecting the glow.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Mara deciphers the magic door's riddle.",
      "visual_description": "Mara presses her ear to the shimmering door, tracing a compass over the symbols, her ink-stained coat brushing the ground.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The glass diver swims through the magic door's surface.",
      "visual_description": "The glass diver presses his helmet against the door, then steps forward and dissolves into its liquid surface, ripples spreading from his point of entry.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Inside the tower, the sleeping tax collector is carried by the group.",
      "visual_description": "The sleeping tax collector is slung over the tin fox's back, still snoring, as Mara and the glass diver navigate a narrow stairwell lit by the oracle lamp.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The oracle lamp reveals a vision of the bridge escape.",
      "visual_description": "The lamp's flame eye projects a flickering image onto a wall: a long stone bridge over a chasm, with armored patrols gathering at its far end.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "Mara recalculates the route using the vision.",
      "visual_description": "Mara quickly redraws a line on her map, her brass compass swinging as she mutters the new coordinates to the tin fox.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The glass diver shatters a window to create a distraction.",
      "visual_description": "The glass diver raises a hand and a nearby window explodes outward in a shower of glittering shards, drawing the attention of distant clanking armor.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The group crosses a crumbling courtyard under old banners.",
      "visual_description": "Mara, the tin fox carrying the sleeping tax collector, and the glass diver hurry past tattered royal banners hanging from broken flagpoles, the oracle lamp held high.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "They reach the bridge but find it guarded by armored figures.",
      "visual_description": "At the bridge's mouth, three empty suits of armor stand motionless, their gauntlets gripping swords, but their helmets slowly turn toward the group.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The glass diver creates a mirror path across the chasm.",
      "visual_description": "The glass diver steps onto the bridge's edge and a series of floating mirrors erupt from the void, forming a shimmering walkway that bypasses the armored figures.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes across the bridge as the city crumbles behind them.",
      "visual_description": "Mara, the glass diver, the oracle lamp, the tin fox carrying the sleeping tax collector, all run across the final mirror pane onto solid ground, the ruined city collapsing into dust behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

